
# --- portable paths (generated by export) -------------------------
# Everything below derives from the repo location; override with env vars
#   COMFYUI_DIR / COMFY_PYTHON / FOUNDRY_PYTHON
$FF_ROOT = if ($PSScriptRoot -and (Test-Path (Join-Path $PSScriptRoot 'app.py'))) {
    $PSScriptRoot
} else {
    Split-Path -Parent $PSScriptRoot
}
$FF_COMFY = if ($env:COMFYUI_DIR) { $env:COMFYUI_DIR } else { Join-Path (Split-Path -Parent $FF_ROOT) 'ComfyUI' }
$FF_COMFY_PY = if ($env:COMFY_PYTHON) { $env:COMFY_PYTHON } else { Join-Path $FF_COMFY 'python.exe' }
$FF_APP_PY = if ($env:FOUNDRY_PYTHON) { $env:FOUNDRY_PYTHON } else { 'python' }
$FF_LOG = Join-Path $FF_ROOT 'logs'
if (-not (Test-Path $FF_LOG)) { New-Item -ItemType Directory -Force -Path $FF_LOG | Out-Null }
# ------------------------------------------------------------------
# AI-Workshop restart (2026-08-18, qwen3.8-27b enhancement architecture)
# Order: free VRAM (kill llama-server 8080) -> Ollama -> ComfyUI -> App
# NOTE: 8081 serve.py (qwen3-14b) is DEPRECATED and no longer started.
#       llama-server (qwen3.8-27b) is auto-started/killed by prompt_enhancer on demand.

$ErrorActionPreference = "Continue"
$logDir = $FF_LOG
New-Item -ItemType Directory -Force -Path $logDir | Out-Null

function Test-Port($port) {
    $c = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue
    return [bool]$c
}

Write-Host "=== AI-Workshop restart (qwen3.8-27b enhance) ===" -ForegroundColor Cyan

# 0. GPU power limit 220W (crash protection; auto-elevates via UAC, never blocks)
& (Join-Path $FF_ROOT 'scripts\set_power_limit.ps1')

# 0. Free VRAM: kill llama-server (8080) if running. It auto-starts on demand during enhancement.
$ll = Get-NetTCPConnection -LocalPort 8080 -State Listen -ErrorAction SilentlyContinue
if ($ll) {
    $pid8080 = $ll[0].OwningProcess
    Stop-Process -Id $pid8080 -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 3
    Write-Host "  (0/3) llama-server(qwen3.8-27b) killed to free VRAM (PID $pid8080)" -ForegroundColor Yellow
} else {
    Write-Host "  (0/3) llama-server not running" -ForegroundColor Green
}

# 1. Ollama (translation + fallback)
if (Test-Port 11434) {
    Write-Host "  (1/3) Ollama  already running" -ForegroundColor Green
} else {
    Write-Host "  (1/3) Ollama  starting..." -ForegroundColor Yellow
    Start-Process ollama -ArgumentList "serve" -WindowStyle Hidden
    $t = 0
    while (-not (Test-Port 11434) -and $t -lt 30) { Start-Sleep -Seconds 1; $t++ }
    if (Test-Port 11434) { Write-Host "  (1/3) Ollama  OK (${t}s)" -ForegroundColor Green }
    else { Write-Host "  (1/3) Ollama  FAILED" -ForegroundColor Red }
}

# 2. ComfyUI x2 (image/3D generation): 8188=GPU0(图片) / 8189=GPU1(视频+3D)
if ((Test-Port 8188) -and (Test-Port 8189)) {
    Write-Host "  (2/3) ComfyUI x2 already running" -ForegroundColor Green
} else {
    Write-Host "  (2/3) ComfyUI x2 starting (py312 + sage)..." -ForegroundColor Yellow
    $env:PYTHONPATH = $null
    Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
    $env:PYTORCH_CUDA_ALLOC_CONF = 'max_split_size_mb:2048,expandable_segments:True'
    $env:OMP_NUM_THREADS = '16'
    $env:MKL_NUM_THREADS = '16'
    $env:HF_ENDPOINT = 'https://hf-mirror.com'
    # 实例 A: GPU0 -> 8188 (image)
    $env:CUDA_VISIBLE_DEVICES = '0'
    Start-Process -FilePath $FF_COMFY_PY `
        -ArgumentList 'main.py','--port','8188','--reserve-vram','4','--use-sage-attention' `
        -WorkingDirectory $FF_COMFY `
        -RedirectStandardOutput (Join-Path $logDir 'comfyui-8188-stdout.log') `
        -RedirectStandardError (Join-Path $logDir 'comfyui-8188-stderr.log') `
        -WindowStyle Hidden | Out-Null
    # 实例 B: GPU1 -> 8189 (video/3d)
    $env:CUDA_VISIBLE_DEVICES = '1'
    Start-Process -FilePath $FF_COMFY_PY `
        -ArgumentList 'main.py','--port','8189','--reserve-vram','4','--use-sage-attention' `
        -WorkingDirectory $FF_COMFY `
        -RedirectStandardOutput (Join-Path $logDir 'comfyui-8189-stdout.log') `
        -RedirectStandardError (Join-Path $logDir 'comfyui-8189-stderr.log') `
        -WindowStyle Hidden | Out-Null
    $t = 0
    while (-not ((Test-Port 8188) -and (Test-Port 8189)) -and $t -lt 150) { Start-Sleep -Seconds 2; $t += 2 }
    if ((Test-Port 8188) -and (Test-Port 8189)) { Write-Host "  (2/3) ComfyUI x2 OK (${t}s)" -ForegroundColor Green }
    else { Write-Host "  (2/3) ComfyUI x2 TIMEOUT, see $logDir\comfyui-8189-stderr.log" -ForegroundColor Red }
}

# 3. App (gradio 7860)
if (Test-Port 7860) {
    Write-Host "  (3/3) App  already running" -ForegroundColor Green
} else {
    Write-Host "  (3/3) App  starting..." -ForegroundColor Yellow
    Start-Process -FilePath $FF_APP_PY `
        -ArgumentList 'app.py' `
        -WorkingDirectory $FF_ROOT `
        -RedirectStandardOutput (Join-Path $logDir 'app-stdout.log') `
        -RedirectStandardError (Join-Path $logDir 'app-stderr.log') `
        -WindowStyle Hidden | Out-Null
    $t = 0
    while (-not (Test-Port 7860) -and $t -lt 90) { Start-Sleep -Seconds 2; $t += 2 }
    if (Test-Port 7860) { Write-Host "  (3/3) App  OK -> http://localhost:7860" -ForegroundColor Green }
    else { Write-Host "  (3/3) App  TIMEOUT, see $logDir\app-stderr.log" -ForegroundColor Red }
}

Write-Host "=== final status ===" -ForegroundColor Cyan
foreach ($p in 11434, 8188, 8189, 7860, 8080) {
    $name = switch ($p) { 11434 {'Ollama'} 8188 {'ComfyUI-img'} 8189 {'ComfyUI-media'} 7860 {'App'} 8080 {'llama-server(enhance)'} }
    $st = if (Test-Port $p) { 'UP' } else { 'DOWN' }
    Write-Host ("  {0,-24} {1,-6} {2}" -f $name, $p, $st)
}
